51	export function aggregateEndpointGroups(
52	  sum: Record<string, number>,
53	  count: Record<string, number>,
54	  endpointGroups: Record<string, readonly string[]>,
55	): Record<string, { averageRequestDurationMs: number; requestCount: number }> {
56	  const result: Record<string, { averageRequestDurationMs: number; requestCount: number }> = {};
57	  for (const [group, endpoints] of Object.entries(endpointGroups)) {
58	    let totalSum = 0;
59	    let totalCount = 0;
60	    for (const endpoint of endpoints) {
61	      totalSum += sum[endpoint] || 0;
62	      totalCount += count[endpoint] || 0;
63	    }
64	    result[group] = {
65	      averageRequestDurationMs: totalCount > 0 ? (totalSum / totalCount) * 1000 : 0,
66	      requestCount: totalCount,
67	    };
68	  }
69	  return result;
70	}
