118	 * Returns an object with all three types of metrics for comprehensive analysis.
119	 */
120	export function parseCompletePrometheusMetrics(text: string): {
121	  sum: Record<string, number>;
122	  count: Record<string, number>;
123	  histograms: Record<string, HistogramBucket[]>;
124	} {
125	  return {
126	    ...parsePrometheusMetrics(text),
127	    histograms: parsePrometheusHistogram(text),
128	  };
129	}
