131	/**
132	 * Aggregates histogram data for endpoint groups by combining multiple endpoints.
133	 * Properly handles cumulative histogram buckets and adds histograms together.
134	 *
135	 * @param histograms - Record of endpoint to histogram data
136	 * @param endpointGroups - Object mapping group name to array of endpoint patterns
137	 * @returns Object mapping group name to aggregated histogram data
138	 */
139	export function aggregateHistogramGroups(
140	  histograms: Record<string, HistogramBucket[]>,
141	  endpointGroups: Record<string, readonly string[]>,
142	): Record<string, HistogramBucket[]> {
143	  const result: Record<string, HistogramBucket[]> = {};
144	
145	  for (const [group, endpoints] of Object.entries(endpointGroups)) {
146	    for (const endpoint of endpoints) {
147	      if (!result[group]) {
148	        // due to etags, a multiple statuses are relevant.
149	        // because they are not merged in previous steps, we have to do this here
150	        // => short-circuiting by setting the result to the histogram would be incorrect
151	        result[group] = [];
152	      }
153	      // Check if histogram data exists for this endpoint
154	      if (histograms[endpoint]) {
155	        for (const bucket of histograms[endpoint]) {
156	          const existingBucket = result[group].find((b) => b.le === bucket.le);
157	          if (existingBucket) {
158	            existingBucket.count += bucket.count;
159	          } else {
160	            result[group].push(bucket);
161	          }
162	        }
163	      }
164	    }
165	  }
166	
167	  // Sort buckets by le value for each group
168	  for (const histogram of Object.values(result)) {
169	    histogram.sort((a, b) => a.le - b.le);
170	  }
171	
172	  return result;
173	}
