14	const fetchAnalytics = async (): Promise<AnalyticsData> => {
15	  const res = await fetch(buildMartinUrl('/_/metrics'));
16	  if (!res.ok) {
17	    throw new Error(`Failed to fetch analytics: ${res.statusText}`);
18	  }
19	  const text = await res.text();
20	  const { sum, count, histograms } = parseCompletePrometheusMetrics(text);
21	
22	  // We want to merge some URLs, such as the many sprite URLs
23	  const groupResults = aggregateEndpointGroups(sum, count, ENDPOINT_GROUPS);
24	  const groupHistograms = aggregateHistogramGroups(histograms, ENDPOINT_GROUPS);
25	
26	  return {
27	    fonts: { ...groupResults.fonts, histogram: groupHistograms.fonts },
28	    sprites: { ...groupResults.sprites, histogram: groupHistograms.sprites },
29	    styles: { ...groupResults.styles, histogram: groupHistograms.styles },
30	    tiles: { ...groupResults.tiles, histogram: groupHistograms.tiles },
31	  };
32	};
