35	  return (
36	    <div className="animate-pulse space-y-6">
37	      {/* Tab navigation skeleton */}
38	      <div className="grid w-full grid-cols-4 h-10 bg-gray-200 rounded-sm"></div>
39	
40	      {/* Content skeleton */}
41	      <div className="space-y-4">
42	        <div className="h-8 bg-gray-200 rounded-sm w-1/3"></div>
43	        <div className="h-4 bg-gray-200 rounded-sm w-2/3"></div>
44	        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
45	          <div className="h-64 bg-gray-200 rounded-sm"></div>
46	          <div className="h-64 bg-gray-200 rounded-sm"></div>
47	          <div className="h-64 bg-gray-200 rounded-sm"></div>
48	        </div>
49	      </div>
50	    </div>
51	  );
52	}
53	
54	export default function MartinTileserverDashboard() {
55	  // Analytics operation
56	  const analyticsOperation = useAsyncOperation<AnalyticsData>(fetchAnalytics, {
57	    onError: (error: Error) => console.error('Analytics fetch failed:', error),
58	    showErrorToast: false,
59	  });
60	
61	  // Load analytics data and set up auto-refresh
62	  useEffect(() => {
63	    // Initial load
64	    analyticsOperation.execute();
65	
66	    // 15-second refresh interval
67	    const interval = setInterval(() => {
68	      analyticsOperation.execute();
69	    }, 15 * 1000);
70	
71	    return () => clearInterval(interval);
72	  }, []);
73	
74	  return (
75	    <div className="container mx-auto px-6 py-8">
76	      <AnalyticsSection
77	        analytics={analyticsOperation.data}
78	        error={analyticsOperation.error}
79	        isLoading={analyticsOperation.isLoading}
80	      />
81	
82	      <Suspense fallback={<DashboardLoading />}>
83	        <DashboardContent />
84	      </Suspense>
85	    </div>
86	  );
87	}
