/**
 * Returns the hit rate as a number in [0, 1] (`hits / (hits + misses)`),
 * or `null` when both hits and misses are zero.
 */
export function hitRate(counts: HitCount): number | null {
  const total = counts.hits + counts.misses;
  if (total > 0) {
    return counts.hits / total;
  }
  return null;
}

