import { MiniHistogram } from '@/components/charts/mini-histogram';
import { ErrorState } from '@/components/error/error-state';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { HoverCard, HoverCardContent, HoverCardTrigger } from '@/components/ui/hover-card';
import { Skeleton } from '@/components/ui/skeleton';
import { type CacheMetrics, hitRate } from '@/lib/prometheus';
import type { AnalyticsData } from '@/lib/types';

interface AnalyticsSectionProps {
  analytics?: AnalyticsData;
  isLoading?: boolean;
  error?: Error | null;
  onRetry?: () => void;
  isRetrying?: boolean;
}

// Display labels for each cache key exposed by the metrics endpoint.
const CACHE_LABELS: Record<string, string> = {
  font: 'Font cache',
  pmtiles_directory: 'PMTiles dirs',
  sprite: 'Sprite cache',
  tile: 'Tile cache',
};

const CARD_CONFIG = [
  {
    // The tile card also surfaces the pmtiles directory cache, both being tile-related.
    cacheKeys: ['tile', 'pmtiles_directory'],
    icon: Layers,
    key: 'tiles',
    title: 'Tiles',
  },
  {
    cacheKeys: [],
    icon: Palette,
    key: 'styles',
    title: 'Styles',
  },
  {
    cacheKeys: ['font'],
    icon: Type,
    key: 'fonts',
    title: 'Fonts',
  },
  {
    cacheKeys: ['sprite'],
    icon: Image,
    key: 'sprites',
    title: 'Sprites',
  },
] as const;

function CacheHitRateRow({ cacheKey, metrics }: { cacheKey: string; metrics: CacheMetrics }) {
  const label = CACHE_LABELS[cacheKey] ?? cacheKey;
  const rate = hitRate(metrics);

  return (
    <div className="flex items-center justify-between gap-2 text-xs">
      <span className="text-muted-foreground">{label}</span>
      <div className="flex items-center gap-1">
        <span className="font-medium tabular-nums">
          {rate === null ? 'no requests yet' : `${(rate * 100).toFixed(1)}% hit`}
        </span>
        {metrics.byZoom.length > 0 && (
          <HoverCard>
            <HoverCardTrigger asChild>
              <button
                aria-label={`${label} hit rate by zoom`}
                className="text-muted-foreground hover:text-foreground"
                type="button"
              >
                <BarChart3 className="h-3.5 w-3.5" />
              </button>
            </HoverCardTrigger>
            <HoverCardContent className="w-56">
              <div className="mb-2 text-xs font-medium">{label} by zoom</div>
              <div className="space-y-1">
                {metrics.byZoom.map((z) => {
                  const zoomRate = hitRate(z);
                  return (
                    <div className="flex items-center justify-between text-xs" key={z.zoom}>
                      <span className="text-muted-foreground">z{z.zoom}</span>
                      <span className="tabular-nums">
                        {zoomRate === null
                          ? 'no requests yet'
                          : `${(zoomRate * 100).toFixed(1)}% hit`}
                      </span>
                    </div>
                  );
                })}
              </div>
            </HoverCardContent>
          </HoverCard>
        )}
      </div>
    </div>
  );
}

export function AnalyticsSection({
  analytics,
  isLoading,
  error = null,
  onRetry,
  isRetrying = false,
}: AnalyticsSectionProps) {
  if (error) {
    return (
      <div className="mb-8">
        <ErrorState
          description="Unable to fetch server metrics and usage data"
          error={error}
          isRetrying={isRetrying}
          onRetry={onRetry}
          showDetails={true}
          title="Failed to Load Analytics"
          variant="server"
        />
      </div>
    );
  }
  return (
    <div className="space-y-6 mb-8">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {CARD_CONFIG.map(({ key, title, icon: Icon, cacheKeys }) => {
          const data = analytics?.[key as keyof AnalyticsData] as
            | AnalyticsData['tiles']
            | undefined;
          const caches = analytics?.caches;
          const cacheRows = caches
            ? cacheKeys.filter((cacheKey) => cacheKey in caches)
            : [];
          return (
            <Card key={key}>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">{title}</CardTitle>
                <Icon className="h-4 w-4 text-primary" />
              </CardHeader>
              <CardContent>
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <div className="text-2xl font-bold flex flex-row gap-1">
                      {isLoading || !data ? (
                        <Skeleton className="h-6 w-12 flex flex-row" />
                      ) : (
                        <>
                          {Math.round(data.averageRequestDurationMs)}
                          {' ms'}
                        </>
                      )}
                    </div>
                    <span className="text-xs text-muted-foreground flex flex-row gap-1">
                      {isLoading || !data ? (
                        <Skeleton className="h-3 w-20" />
                      ) : (
                        <>
                          {data.requestCount.toLocaleString()}
                          {' requests'}
                        </>
                      )}
                    </span>
                  </div>
                  <div className="flex items-center">
                    {data?.histogram ? (
                      <MiniHistogram histogram={data.histogram} />
                    ) : (
                      <div className="w-20 h-12 bg-muted/10 rounded-md opacity-40 animate-pulse bg-linear-to-r from-transparent to-muted"></div>
                    )}
                  </div>
                </div>
                {cacheRows.length > 0 && caches && (
                  <div className="mt-4 space-y-1 border-t pt-3">
                    {cacheRows.map((cacheKey) => (
                      <CacheHitRateRow
                        cacheKey={cacheKey}
                        key={cacheKey}
                        metrics={caches[cacheKey]}
                      />
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
